using System.Collections.Immutable;
using System.Reflection;
using System.Reflection.Metadata;
using System.Reflection.Metadata.Ecma335;
using System.Reflection.PortableExecutable;
using System.Reflection.Emit;
using var f=File.OpenRead(args[0]);using var pe=new PEReader(f);var r=pe.GetMetadataReader();var provider=new Types();
Console.WriteLine($"META definedTypes={r.TypeDefinitions.Count} exportedTypes={r.ExportedTypes.Count}");
foreach(var eh in r.ExportedTypes){var e=r.GetExportedType(eh);Console.WriteLine("EXPORTED "+r.GetString(e.Namespace)+"."+r.GetString(e.Name));}
string Name(TypeDefinitionHandle h)=>provider.GetTypeFromDefinition(r,h,0);
foreach(var ah in r.AssemblyReferences) Console.WriteLine("REF "+r.GetString(r.GetAssemblyReference(ah).Name));
foreach(var th in r.TypeDefinitions){
 var t=r.GetTypeDefinition(th);
 if((t.Attributes & TypeAttributes.VisibilityMask) is not (TypeAttributes.Public or TypeAttributes.NestedPublic))continue;
 var name=Name(th);if(args.Length>1&&!name.Contains(args[1]))continue;
 Console.WriteLine("TYPE "+name+" base="+(t.BaseType.IsNil?"":provider.Handle(r,t.BaseType)));
 foreach(var ih in t.GetInterfaceImplementations())Console.WriteLine("  implements "+provider.Handle(r,r.GetInterfaceImplementation(ih).Interface));
 foreach(var fh in t.GetFields()){var v=r.GetFieldDefinition(fh);if((v.Attributes&FieldAttributes.FieldAccessMask)!=FieldAttributes.Public)continue;Console.WriteLine("  FIELD "+v.DecodeSignature(provider,(object?)null)+" "+r.GetString(v.Name));}
 foreach(var mh in t.GetMethods()){var m=r.GetMethodDefinition(mh);if((m.Attributes & MethodAttributes.MemberAccessMask)!=MethodAttributes.Public)continue;var s=m.DecodeSignature(provider,(object?)null);Console.WriteLine("  "+((m.Attributes&MethodAttributes.Static)!=0?"static ":"")+s.ReturnType+" "+r.GetString(m.Name)+"("+string.Join(", ",s.ParameterTypes)+")");}
}
if(args.Length>2 && args[2]=="IL"){
 var ops=typeof(OpCodes).GetFields().Where(x=>x.FieldType==typeof(OpCode)).Select(x=>(OpCode)x.GetValue(null)!).ToDictionary(x=>(ushort)x.Value);
 string Token(int n){try{var h=MetadataTokens.EntityHandle(n);return h.Kind switch{
 HandleKind.MemberReference=>Member((MemberReferenceHandle)h),HandleKind.MethodDefinition=>r.GetString(r.GetMethodDefinition((MethodDefinitionHandle)h).Name),
 HandleKind.MethodSpecification=>Spec((MethodSpecificationHandle)h),HandleKind.FieldDefinition=>r.GetString(r.GetFieldDefinition((FieldDefinitionHandle)h).Name),
 HandleKind.TypeReference=>provider.GetTypeFromReference(r,(TypeReferenceHandle)h,0),HandleKind.TypeDefinition=>Name((TypeDefinitionHandle)h),_=>h.Kind+":"+n.ToString("X8")};}catch{return n.ToString("X8");}}
 string Spec(MethodSpecificationHandle h){var s=r.GetMethodSpecification(h);return Token(MetadataTokens.GetToken(s.Method))+"<"+string.Join(",",s.DecodeSignature(provider,(object?)null))+">";}
 string Member(MemberReferenceHandle h){var v=r.GetMemberReference(h);return provider.Handle(r,v.Parent)+"."+r.GetString(v.Name);}
 foreach(var th in r.TypeDefinitions){var t=r.GetTypeDefinition(th);if(!Name(th).Contains(args[1]))continue;
 foreach(var mh in t.GetMethods()){var m=r.GetMethodDefinition(mh);if(m.RelativeVirtualAddress==0)continue;
 Console.WriteLine("IL "+Name(th)+"."+r.GetString(m.Name));var b=pe.GetMethodBody(m.RelativeVirtualAddress).GetILBytes()!;
 for(int i=0;i<b.Length;){int off=i;ushort c=b[i++];if(c==254)c=(ushort)(0xfe00|b[i++]);var op=ops[c];int n=op.OperandType switch{OperandType.InlineNone=>0,OperandType.ShortInlineBrTarget or OperandType.ShortInlineI or OperandType.ShortInlineVar=>1,OperandType.InlineVar=>2,OperandType.InlineI8 or OperandType.InlineR=>8,OperandType.InlineSwitch=>4+4*BitConverter.ToInt32(b,i),_=>4};
 string v=n==4?BitConverter.ToInt32(b,i).ToString():Convert.ToHexString(b.AsSpan(i,n));
 if(op.OperandType is OperandType.InlineMethod or OperandType.InlineType or OperandType.InlineTok or OperandType.InlineField)v=Token(BitConverter.ToInt32(b,i));
 if(op.OperandType==OperandType.InlineString)v=r.GetUserString(MetadataTokens.UserStringHandle(BitConverter.ToInt32(b,i)&0xffffff));
 Console.WriteLine($" {off:X4} {op.Name} {v}");i+=n;}}}
}
class Types:ISignatureTypeProvider<string,object?>{
 public string Handle(MetadataReader r,EntityHandle h)=>h.Kind switch{HandleKind.TypeDefinition=>GetTypeFromDefinition(r,(TypeDefinitionHandle)h,0),HandleKind.TypeReference=>GetTypeFromReference(r,(TypeReferenceHandle)h,0),HandleKind.TypeSpecification=>GetTypeFromSpecification(r,null,(TypeSpecificationHandle)h,0),_=>h.Kind.ToString()};
 public string GetTypeFromDefinition(MetadataReader r,TypeDefinitionHandle h,byte k){var t=r.GetTypeDefinition(h);return t.GetDeclaringType().IsNil?r.GetString(t.Namespace)+"."+r.GetString(t.Name):GetTypeFromDefinition(r,t.GetDeclaringType(),0)+"+"+r.GetString(t.Name);}
 public string GetTypeFromReference(MetadataReader r,TypeReferenceHandle h,byte k){var t=r.GetTypeReference(h);return r.GetString(t.Namespace)+"."+r.GetString(t.Name);}
 public string GetTypeFromSpecification(MetadataReader r,object? c,TypeSpecificationHandle h,byte k)=>r.GetTypeSpecification(h).DecodeSignature(this,c);
 public string GetArrayType(string e,ArrayShape s)=>e+"["+new string(',',s.Rank-1)+"]";
 public string GetByReferenceType(string e)=>e+"&";
 public string GetFunctionPointerType(MethodSignature<string> s)=>"fnptr("+string.Join(",",s.ParameterTypes)+")->"+s.ReturnType;
 public string GetGenericInstantiation(string g,ImmutableArray<string>a)=>g+"<"+string.Join(",",a)+">";
 public string GetGenericMethodParameter(object?c,int i)=>"!!"+i;
 public string GetGenericTypeParameter(object?c,int i)=>"!"+i;
 public string GetModifiedType(string m,string u,bool req)=>u;
 public string GetPinnedType(string e)=>e;
 public string GetPointerType(string e)=>e+"*";
 public string GetPrimitiveType(PrimitiveTypeCode c)=>c.ToString();
 public string GetSZArrayType(string e)=>e+"[]";
}

