using System.Text;
using Brutal.GlfwApi;
using Brutal.ImGuiApi;
public static class FontProbe {
 public static ImFontPtr Load(ImGuiIOPtr io, string path, float pixels) {
   var font=io.Fonts.AddFontFromFileTTF(Encoding.UTF8.GetBytes(path), pixels);
   io.FontDefault=font;
   var source=font.Sources[0];
   _=source.FontDataSize; _=source.RasterizerDensity; _=source.PixelSnapH;
   io.ConfigDpiScaleFonts=false;
   ImGui.GetStyle().FontScaleMain=1; ImGui.GetStyle().FontScaleDpi=1;
   var baked=font.GetFontBaked(pixels, 2);
   _=baked.RasterizerDensity; _=baked.Size;
   return font;
 }
 public static bool Key(GlfwWindow window) => window.GetKey(GlfwKey.F1)==GlfwKeyAction.Press;
}
